function slugify(value: string) {
  const base = value.normalize("NFKD").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 48);
  return `${base || "community"}-${Math.random().toString(36).slice(2, 8)}`;
}

