  return <div className="mt-3 flex gap-2"><input value={text} onChange={(event) => setText(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && text.trim()) { void onSend(text); setText(""); } }} placeholder="Γράψε σχόλιο…" className="min-w-0 flex-1 rounded-full border border-slate-200 px-3 py-2 text-sm"/><button onClick={() => { if (text.trim()) { void onSend(text); setText(""); } }} className="rounded-full bg-slate-900 px-3 py-2 text-sm font-bold text-white">Αποστολή</button></div>;
}

